  1	//! Signature verification, and a token that can only exist because it happened.
  2	//!
  3	//! Tauri does not verify what you hand it. `tauri-plugin-updater` calls
  4	//! `verify_signature` from exactly one place — inside `Update::download()` — and
  5	//! the handoff seam, `Update::install(bytes)`, goes straight to the installer.
  6	//! The delta path exists to avoid that download, so this plugin's own check is
  7	//! the *only* thing standing between a reconstructed artifact and installation.
  8	//! See `docs/DECISIONS.md` #10.
  9	//!
 10	//! A sole gate with no backstop should not depend on every call site remembering
 11	//! to pass through it. So it is enforced by the type system instead:
 12	//! [`VerifiedArtifact`] has a private field and no public constructor, which
 13	//! means [`verify_artifact`] is the only way in the language to obtain one. A
 14	//! handoff that accepts `&VerifiedArtifact` cannot be called with unverified
 15	//! bytes — not by a mistake, not by a future refactor, and not by a second entry
 16	//! point someone adds later without reading this file.
 17	//!
 18	//! This is the same move as [`Reconstruction`](crate::Reconstruction) making the
 19	//! fallback unavoidable: put the invariant where the compiler enforces it rather
 20	//! than where a reviewer has to notice it.
 21	//!
 22	//! # Why bytes rather than a path
 23	//!
 24	//! The token owns the bytes that were verified, not a path to them. A path would
 25	//! leave a window between the check and the install in which the file could be
 26	//! replaced, and the signature would then describe something other than what
 27	//! gets installed. Holding the bytes closes it: what was verified and what is
 28	//! handed over are the same allocation.
 29	//!
 30	//! The cost is keeping the artifact resident. Tauri's own `download()` does
 31	//! exactly this — `let mut buffer = Vec::new()` — so this is no worse than the
 32	//! path it replaces.
 33	//!
 34	//! # Verification itself
 35	//!
 36	//! Reproduced from `tauri-plugin-updater` 2.10.1, `src/updater.rs:1453`, rather
 37	//! than reimplemented, so the artifact this plugin accepts is precisely the
 38	//! artifact Tauri would have accepted. `tauri_signature_compat.rs` pins that
 39	//! equivalence.
 40	
 41	use std::path::Path;
 42	
 43	use base64::Engine as _;
 44	use minisign_verify::{PublicKey, Signature};
 45	
 46	use crate::{Error, Result};
 47	
 48	/// An artifact whose minisign signature has been verified.
 49	///
 50	/// The only way to construct one is [`verify_artifact`]. Take this type as a
 51	/// parameter wherever an unverified artifact must be impossible to supply.
 52	///
 53	/// Deliberately not `Deserialize`, not `Default`, and carrying no public field —
 54	/// each of those would be a way to mint the proof without doing the work.
 55	///
 56	/// The guarantee is the compiler's, not a convention. Forging the token does not
 57	/// fail a review; it fails to build:
 58	///
 59	/// ```compile_fail
 60	/// use tauri_updater_delta_core::VerifiedArtifact;
 61	/// // error[E0451]: field `bytes` of struct `VerifiedArtifact` is private
 62	/// let forged = VerifiedArtifact { bytes: b"unverified".to_vec() };
 63	/// ```
 64	///
 65	/// ```compile_fail
 66	/// use tauri_updater_delta_core::VerifiedArtifact;
 67	/// // No Default, no From<Vec<u8>>, no other way in.
 68	/// let forged: VerifiedArtifact = Default::default();
 69	/// ```
 70	///
 71	/// And the honest limit: within *this* crate the field is reachable, so the
 72	/// guarantee is that no code outside `delta-core` can mint one. Inside it, this
 73	/// module is the only place that constructs the type, and that is deliberately a
 74	/// small surface to keep under review.
 75	#[derive(Debug, Clone)]
 76	pub struct VerifiedArtifact {
 77	    /// Private. This is the whole mechanism.
 78	    bytes: Vec<u8>,
 79	}
 80	
 81	impl VerifiedArtifact {
 82	    /// The verified bytes — exactly those the signature was checked against.
 83	    pub fn as_bytes(&self) -> &[u8] {
 84	        &self.bytes
 85	    }
 86	
 87	    /// Size of the artifact in bytes.
 88	    pub fn len(&self) -> usize {
 89	        self.bytes.len()
 90	    }
 91	
 92	    /// Whether the artifact is empty.
 93	    pub fn is_empty(&self) -> bool {
 94	        self.bytes.is_empty()
 95	    }
 96	
 97	    /// Consume the token, yielding the bytes.
 98	    ///
 99	    /// Named to be conspicuous at a call site: past this point the proof is
100	    /// gone and the bytes are ordinary again. Hand a `&VerifiedArtifact` around
101	    /// instead wherever that is possible.
102	    pub fn into_unverified_bytes(self) -> Vec<u8> {
103	        self.bytes
104	    }
105	}
106	
107	/// Verify `bytes` against a base64 minisign signature and public key.
108	///
109	/// Both encodings are Tauri's: base64 of the whole minisign file, comment line
110	/// included, exactly as stored in a manifest and in `tauri.conf.json`.
111	pub fn verify_artifact(
112	    bytes: Vec<u8>,
113	    signature_b64: &str,
114	    pubkey_b64: &str,
115	) -> Result<VerifiedArtifact> {
116	    // Reproduces tauri-plugin-updater's verify_signature step for step. Note
117	    // PublicKey::decode over the whole key file, not from_base64 over the key
118	    // line — Tauri does the former, and the two are easy to confuse.
119	    let pubkey_decoded = base64_to_string(pubkey_b64, "public key")?;
120	    let public_key = PublicKey::decode(&pubkey_decoded)
121	        .map_err(|e| Error::Signature(format!("unusable public key: {e}")))?;
122	
123	    let signature_decoded = base64_to_string(signature_b64, "signature")?;
124	    let signature = Signature::decode(&signature_decoded)
125	        .map_err(|e| Error::Signature(format!("unusable signature: {e}")))?;
126	
127	    public_key
128	        .verify(&bytes, &signature, true)
129	        .map_err(|e| Error::Signature(e.to_string()))?;
130	
131	    Ok(VerifiedArtifact { bytes })
132	}
133	
134	/// Read `path` and verify it.
135	pub fn verify_artifact_file(
136	    path: &Path,
137	    signature_b64: &str,
138	    pubkey_b64: &str,
139	) -> Result<VerifiedArtifact> {
140	    let bytes = std::fs::read(path).map_err(|e| Error::io("read", path, e))?;
141	    verify_artifact(bytes, signature_b64, pubkey_b64)
142	}
143	
144	fn base64_to_string(value: &str, what: &str) -> Result<String> {
145	    let decoded = base64::engine::general_purpose::STANDARD
146	        .decode(value)
147	        .map_err(|e| Error::Signature(format!("{what} is not valid base64: {e}")))?;
148	    String::from_utf8(decoded)
149	        .map_err(|_| Error::Signature(format!("{what} did not decode to text")))
150	}
151	
152	#[cfg(test)]
153	mod tests {
154	    use super::*;
155	
156	    /// Fixed keypair and signature over `b"the released installer"`, generated
157	    /// once with the `minisign` crate and pinned here so this module needs no
158	    /// signing dependency.
159	    const PUBKEY: &str = "dW50cnVzdGVkIGNvbW1lbnQ6IG1pbmlzaWduIHB1YmxpYyBrZXkKUldRZjYyWm5NRlZUOFRQTVh4b3Nia3RtY29ScTB2VC9kSFdTeGxWVHBmZFVKM3lWWmVDdWZlWG4K";
160	
161	    fn sample() -> (Vec<u8>, String, String) {
162	        // Generated at test time rather than pinned, so this stays correct if
163	        // the encoding changes; the pinned-key path is covered by the
164	        // compatibility suite in the release crate.
165	        let pair = minisign::KeyPair::generate_encrypted_keypair(Some(String::new()))
166	            .expect("generate keypair");
167	        let bytes = b"the released installer".to_vec();
168	
169	        let signature = minisign::sign(None, &pair.sk, &bytes[..], None, None)
170	            .expect("sign")
171	            .into_string();
172	        let signature_b64 = base64::engine::general_purpose::STANDARD.encode(signature);
173	
174	        let pubkey = pair.pk.to_box().expect("box pk").into_string();
175	        let pubkey_b64 = base64::engine::general_purpose::STANDARD.encode(pubkey);
176	
177	        (bytes, signature_b64, pubkey_b64)
178	    }
179	
180	    #[test]
181	    fn a_valid_signature_yields_a_token() {
182	        let (bytes, signature, pubkey) = sample();
183	        let verified = verify_artifact(bytes.clone(), &signature, &pubkey).expect("should verify");
184	        assert_eq!(verified.as_bytes(), &bytes[..]);
185	        assert_eq!(verified.len(), bytes.len());
186	        assert!(!verified.is_empty());
187	    }
188	
189	    #[test]
190	    fn the_token_carries_the_bytes_that_were_checked() {
191	        // Not a path that could be swapped afterwards — the proof and the
192	        // payload are the same allocation.
193	        let (bytes, signature, pubkey) = sample();
194	        let verified = verify_artifact(bytes.clone(), &signature, &pubkey).expect("should verify");
195	        assert_eq!(verified.into_unverified_bytes(), bytes);
196	    }
197	
198	    #[test]
199	    fn tampered_bytes_produce_no_token() {
200	        let (_, signature, pubkey) = sample();
201	        let err = verify_artifact(b"a different installer".to_vec(), &signature, &pubkey)
202	            .expect_err("must not verify");
203	        assert!(matches!(err, Error::Signature(_)), "unexpected: {err}");
204	    }
205	
206	    #[test]
207	    fn another_keys_signature_produces_no_token() {
208	        let (bytes, signature, _) = sample();
209	        let (_, _, other_pubkey) = sample();
210	        assert!(verify_artifact(bytes, &signature, &other_pubkey).is_err());
211	    }
212	
213	    #[test]
214	    fn malformed_inputs_produce_no_token() {
215	        let (bytes, signature, pubkey) = sample();
216	        assert!(verify_artifact(bytes.clone(), "not base64!", &pubkey).is_err());
217	        assert!(verify_artifact(bytes.clone(), &signature, "not base64!").is_err());
218	        assert!(verify_artifact(bytes, "", "").is_err());
219	    }
220	
221	    #[test]
222	    fn a_pinned_tauri_style_public_key_decodes() {
223	        // Guards the encoding itself: Tauri stores base64 of the whole .pub
224	        // file, and PublicKey::decode expects that file's text.
225	        let decoded = base64_to_string(PUBKEY, "public key").expect("decode");
226	        assert!(decoded.starts_with("untrusted comment:"));
227	        PublicKey::decode(&decoded).expect("a real Tauri-style public key should parse");
228	    }
229	
230	    #[test]
231	    fn verifies_from_a_file() {
232	        let dir = tempfile::tempdir().expect("temp dir");
233	        let (bytes, signature, pubkey) = sample();
234	        let path = dir.path().join("app.AppImage");
235	        std::fs::write(&path, &bytes).expect("write");
236	
237	        let verified = verify_artifact_file(&path, &signature, &pubkey).expect("should verify");
238	        assert_eq!(verified.as_bytes(), &bytes[..]);
239	
240	        // Swapping the file afterwards cannot affect the token.
241	        std::fs::write(&path, b"swapped after verification").expect("overwrite");
242	        assert_eq!(verified.as_bytes(), &bytes[..]);
243	    }
244	}
  1	//! The delta path, with the fallback guarantee expressed in the type system.
  2	//!
  3	//! Everything about this project rests on one promise: *the delta path can make
  4	//! an update faster, but it can never make one fail.* [`try_reconstruct`]
  5	//! enforces that by not being fallible. It returns a [`Reconstruction`], and the
  6	//! only two possibilities are "here is a verified artifact" and "download the
  7	//! full one" — there is no error to accidentally propagate out of the delta path
  8	//! and abort an install.
  9	//!
 10	//! A patch is untrusted input, so a successful decompression proves nothing on
 11	//! its own. Three gates stand between a patch and an install:
 12	//!
 13	//! 1. **Size** — the manifest declares the target installer's length, which also
 14	//!    bounds the memory zstd may allocate before decompression begins.
 15	//! 2. **Digest** — the reconstruction must hash to the value the release process
 16	//!    published.
 17	//! 3. **Signature** — verified by the caller against the same minisign key
 18	//!    Tauri's own updater uses, over that same artifact.
 19	//!
 20	//! Failing any of them costs a wasted download, never a broken install.
 21	
 22	use std::path::{Path, PathBuf};
 23	
 24	use crate::backend::{backend_for, PatchBackend, ZstdBackend};
 25	use crate::hash::verify_file;
 26	use crate::{Error, FileHash, Result};
 27	
 28	/// What the manifest promises about the artifact being rebuilt.
 29	#[derive(Debug, Clone)]
 30	pub struct TargetSpec {
 31	    /// Backend that produced the patch, from the manifest.
 32	    pub backend_id: String,
 33	    /// Exact size of the target installer in bytes.
 34	    pub size: u64,
 35	    /// Digest the reconstruction must match.
 36	    pub digest: FileHash,
 37	}
 38	
 39	impl TargetSpec {
 40	    /// Build a spec from the raw manifest fields.
 41	    pub fn new(backend_id: impl Into<String>, size: u64, digest_hex: &str) -> Result<Self> {
 42	        Ok(Self {
 43	            backend_id: backend_id.into(),
 44	            size,
 45	            digest: FileHash::from_hex(digest_hex)?,
 46	        })
 47	    }
 48	}
 49	
 50	/// The outcome of attempting the delta path.
 51	///
 52	/// Deliberately not a `Result`: there is no failure mode here that a caller is
 53	/// expected to propagate. Both variants are normal.
 54	#[derive(Debug)]
 55	#[must_use = "ignoring this discards the decision about whether to download the full artifact"]
 56	pub enum Reconstruction {
 57	    /// The artifact was rebuilt and passed every check. Ready for the installer.
 58	    Verified(PathBuf),
 59	
 60	    /// The delta path did not work out. Download the full artifact as usual.
 61	    ///
 62	    /// The reason is carried for logging, not for the caller to act on
 63	    /// differently — every reason leads to the same recovery.
 64	    FallBack(Error),
 65	}
 66	
 67	impl Reconstruction {
 68	    /// The rebuilt artifact, if the delta path succeeded.
 69	    pub fn verified_path(&self) -> Option<&Path> {
 70	        match self {
 71	            Self::Verified(path) => Some(path),
 72	            Self::FallBack(_) => None,
 73	        }
 74	    }
 75	
 76	    /// Why the delta path was abandoned, if it was.
 77	    pub fn fallback_reason(&self) -> Option<&Error> {
 78	        match self {
 79	            Self::Verified(_) => None,
 80	            Self::FallBack(reason) => Some(reason),
 81	        }
 82	    }
 83	}
 84	
 85	/// Rebuild an installer from `base` and `patch`, verifying it against `target`.
 86	///
 87	/// Never fails. Anything that goes wrong — an unknown backend, a corrupt or
 88	/// truncated patch, the wrong base version, a size or digest mismatch, a full
 89	/// disk — produces [`Reconstruction::FallBack`].
 90	///
 91	/// The caller is still responsible for the signature check, which needs the
 92	/// public key and therefore belongs to the layer that holds configuration.
 93	pub fn try_reconstruct(
 94	    base: &Path,
 95	    patch: &Path,
 96	    out: &Path,
 97	    target: &TargetSpec,
 98	) -> Reconstruction {
 99	    match reconstruct_inner(base, patch, out, target) {
100	        Ok(()) => Reconstruction::Verified(out.to_path_buf()),
101	        Err(reason) => {
102	            // Never leave a half-written artifact where something might mistake
103	            // it for a finished download.
104	            let _ = std::fs::remove_file(out);
105	            Reconstruction::FallBack(reason)
106	        }
107	    }
108	}
109	
110	fn reconstruct_inner(base: &Path, patch: &Path, out: &Path, target: &TargetSpec) -> Result<()> {
111	    // Resolving by id means a client that meets a backend it does not implement
112	    // declines the patch instead of guessing at the format.
113	    let backend = backend_for(&target.backend_id)?;
114	
115	    if backend.id() == ZstdBackend::ID {
116	        // Bound the window and the output by the size the manifest committed to,
117	        // rather than by what the patch's own header claims.
118	        ZstdBackend::new()
119	            .with_expected_output_bytes(target.size)
120	            .apply(base, patch, out)?;
121	    } else {
122	        backend.apply(base, patch, out)?;
123	    }
124	
125	    verify_file(out, &target.digest)
126	}
127	
128	#[cfg(test)]
129	mod tests {
130	    use super::*;
131	
132	    fn spec(size: u64, digest: FileHash) -> TargetSpec {
133	        TargetSpec {
134	            backend_id: ZstdBackend::ID.to_owned(),
135	            size,
136	            digest,
137	        }
138	    }
139	
140	    #[test]
141	    fn an_unknown_backend_falls_back_rather_than_erroring() {
142	        let dir = tempfile::tempdir().expect("temp dir");
143	        let out = dir.path().join("out.bin");
144	        let target = TargetSpec {
145	            backend_id: "some-future-backend".to_owned(),
146	            size: 10,
147	            digest: FileHash::of_bytes(b"whatever"),
148	        };
149	
150	        let outcome = try_reconstruct(
151	            &dir.path().join("base.bin"),
152	            &dir.path().join("patch.bin"),
153	            &out,
154	            &target,
155	        );
156	
157	        assert!(matches!(
158	            outcome.fallback_reason(),
159	            Some(Error::UnknownBackend(_))
160	        ));
161	    }
162	
163	    #[test]
164	    fn a_missing_base_falls_back() {
165	        let dir = tempfile::tempdir().expect("temp dir");
166	        let out = dir.path().join("out.bin");
167	        let outcome = try_reconstruct(
168	            &dir.path().join("absent.bin"),
169	            &dir.path().join("absent.patch"),
170	            &out,
171	            &spec(10, FileHash::of_bytes(b"x")),
172	        );
173	        assert!(outcome.verified_path().is_none());
174	    }
175	
176	    #[test]
177	    fn a_failed_reconstruction_leaves_no_artifact_behind() {
178	        let dir = tempfile::tempdir().expect("temp dir");
179	        let base = dir.path().join("base.bin");
180	        let patch = dir.path().join("bad.patch");
181	        let out = dir.path().join("out.bin");
182	        std::fs::write(&base, b"the base artifact").expect("write base");
183	        std::fs::write(&patch, b"this is not a zstd frame").expect("write patch");
184	
185	        let outcome = try_reconstruct(&base, &patch, &out, &spec(17, FileHash::of_bytes(b"x")));
186	
187	        assert!(outcome.verified_path().is_none());
188	        assert!(
189	            !out.exists(),
190	            "a half-written artifact must not survive a failed reconstruction"
191	        );
192	    }
193	}
  1	//! The release manifest: a superset of Tauri's static updater JSON.
  2	//!
  3	//! # Why a superset
  4	//!
  5	//! The delta path is an optimisation that must never become a dependency, which
  6	//! means the full-download fallback has to keep working exactly as it does
  7	//! today. The cheapest way to guarantee that is to make this document *be* the
  8	//! official updater's manifest, with the delta information added alongside
  9	//! rather than replacing anything.
 10	//!
 11	//! A Tauri client that knows nothing about deltas reads [`version`],
 12	//! [`pub_date`] and [`platforms`] and behaves normally. A delta-aware client
 13	//! reads the same fields, plus [`delta`]. There is no second document to publish
 14	//! and no way for the two views to drift apart.
 15	//!
 16	//! [`version`]: Manifest::version
 17	//! [`pub_date`]: Manifest::pub_date
 18	//! [`platforms`]: Manifest::platforms
 19	//! [`delta`]: Manifest::delta
 20	//!
 21	//! # Shape
 22	//!
 23	//! ```json
 24	//! {
 25	//!   "version": "1.0.1",
 26	//!   "pub_date": "2026-08-12T10:00:00Z",
 27	//!   "platforms": {
 28	//!     "linux-x86_64": {
 29	//!       "url": "https://releases.example.com/app_1.0.1.AppImage",
 30	//!       "signature": "<minisign signature over that installer>"
 31	//!     }
 32	//!   },
 33	//!   "delta": {
 34	//!     "schema": 1,
 35	//!     "hash_algo": "blake3",
 36	//!     "platforms": {
 37	//!       "linux-x86_64": {
 38	//!         "target_version": "1.0.1",
 39	//!         "target_installer_blake3": "…",
 40	//!         "target_installer_size": 6815744,
 41	//!         "signature": "<the same minisign signature>",
 42	//!         "patches": {
 43	//!           "1.0.0": {
 44	//!             "backend_id": "zstd",
 45	//!             "patch_url": "https://releases.example.com/1.0.0-to-1.0.1.zst",
 46	//!             "patch_blake3": "…",
 47	//!             "patch_size": 393782
 48	//!           }
 49	//!         }
 50	//!       }
 51	//!     }
 52	//!   }
 53	//! }
 54	//! ```
 55	//!
 56	//! # What the signature covers
 57	//!
 58	//! [`signature`](DeltaPlatform::signature) is over the **target installer** —
 59	//! the artifact that actually gets installed — not over the patch. Both paths
 60	//! converge on the same file, so both validate against the same signature, and
 61	//! the delta path cannot install anything the full-download path would have
 62	//! rejected.
 63	//!
 64	//! Hash fields carry their algorithm in the name, and [`DeltaLayer::hash_algo`]
 65	//! states it explicitly, so a client can refuse a document it cannot check
 66	//! instead of comparing a BLAKE3 digest against a SHA-256 field.
 67	//!
 68	//! # Version coverage
 69	//!
 70	//! Schema 1 is patch-from-any-previous-to-latest: every entry in
 71	//! [`patches`](DeltaPlatform::patches) reconstructs the *current* release. There
 72	//! are no multi-hop chains, so a client is never asked to apply two patches in
 73	//! sequence. Chaining is future work and would arrive as `schema: 2`.
 74	
 75	use std::collections::BTreeMap;
 76	
 77	use serde::{Deserialize, Serialize};
 78	
 79	use crate::{Error, FileHash, Result};
 80	
 81	/// Schema version this build writes and understands.
 82	pub const SCHEMA_VERSION: u32 = 1;
 83	
 84	/// Name recorded in [`DeltaLayer::hash_algo`] for the digests this crate produces.
 85	pub const HASH_ALGO: &str = "blake3";
 86	
 87	/// A release manifest: Tauri's static updater document plus a delta layer.
 88	#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
 89	pub struct Manifest {
 90	    /// Version being released, e.g. `"1.0.1"`.
 91	    pub version: String,
 92	
 93	    /// Release notes, surfaced by Tauri's updater.
 94	    #[serde(default, skip_serializing_if = "Option::is_none")]
 95	    pub notes: Option<String>,
 96	
 97	    /// RFC 3339 publication timestamp.
 98	    #[serde(default, skip_serializing_if = "Option::is_none")]
 99	    pub pub_date: Option<String>,
100	
101	    /// Full-download targets, keyed by Tauri's `{os}-{arch}` identifier.
102	    ///
103	    /// This is the fallback path, and it is the official updater's own field —
104	    /// untouched, so a delta-unaware client works against this document as-is.
105	    pub platforms: BTreeMap<String, TauriPlatform>,
106	
107	    /// Delta information. Absent means no patches are published for this release.
108	    #[serde(default, skip_serializing_if = "Option::is_none")]
109	    pub delta: Option<DeltaLayer>,
110	}
