112	/// One full-download target, in Tauri's own format.
113	#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
114	pub struct TauriPlatform {
115	    /// Where the complete installer artifact can be downloaded.
116	    pub url: String,
117	    /// Base64 minisign signature over the installer at `url`.
118	    pub signature: String,
119	}
