121	/// The delta layer added on top of Tauri's document.
122	#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
123	pub struct DeltaLayer {
124	    /// Schema version; a client refuses anything it does not implement.
125	    pub schema: u32,
126	    /// Digest algorithm used by every hash field below.
127	    pub hash_algo: String,
128	    /// Delta targets, keyed by the same `{os}-{arch}` identifier as `platforms`.
129	    pub platforms: BTreeMap<String, DeltaPlatform>,
130	}
