132	/// Delta information for one platform.
133	#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
134	pub struct DeltaPlatform {
135	    /// Version every patch here reconstructs. Matches [`Manifest::version`].
136	    pub target_version: String,
137	
138	    /// Digest of the installer a patch must reproduce.
139	    ///
140	    /// This is the gate: a reconstruction that does not hash to this value is
141	    /// discarded and the full artifact downloaded instead.
142	    pub target_installer_blake3: String,
143	
144	    /// Size in bytes of that installer.
145	    ///
146	    /// Used to bound decompression before it starts — both the output written
147	    /// and the window zstd is permitted to allocate — so a hostile patch cannot
148	    /// force an unbounded allocation.
149	    pub target_installer_size: u64,
150	
151	    /// Base64 minisign signature over the target installer.
152	    ///
153	    /// Deliberately the same value as the matching [`TauriPlatform::signature`],
154	    /// because both paths install the same artifact. [`Manifest::validate`]
155	    /// rejects a document where the two disagree.
156	    pub signature: String,
157	
158	    /// Patches into this release, keyed by the version being upgraded *from*.
159	    pub patches: BTreeMap<String, Patch>,
160	}
