162	/// A single patch, from one previous version to the release.
163	#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
164	pub struct Patch {
165	    /// Backend that produced it, e.g. `"zstd"`. A client that does not have this
166	    /// backend declines the patch and falls back.
167	    pub backend_id: String,
168	    /// Where the patch can be downloaded.
169	    pub patch_url: String,
170	    /// Digest of the patch file itself, checked before it is applied.
171	    pub patch_blake3: String,
172	    /// Size of the patch in bytes.
173	    pub patch_size: u64,
174	}
