176	impl Manifest {
177	    /// Parse a manifest and check its invariants.
178	    pub fn from_json(json: &str) -> Result<Self> {
179	        let manifest: Self =
180	            serde_json::from_str(json).map_err(|e| Error::Manifest(e.to_string()))?;
181	        manifest.validate()?;
182	        Ok(manifest)
183	    }
184	
185	    /// Serialize as pretty-printed JSON.
186	    pub fn to_json(&self) -> Result<String> {
187	        serde_json::to_string_pretty(self).map_err(|e| Error::Manifest(e.to_string()))
188	    }
189	
190	    /// Check the invariants that keep the two layers describing the same release.
191	    ///
192	    /// The delta layer duplicates information the Tauri layer already carries.
193	    /// That redundancy is deliberate — it keeps each layer independently
194	    /// readable — but redundancy that is never checked is just an opportunity to
195	    /// disagree, so it is checked here on every load.
196	    pub fn validate(&self) -> Result<()> {
197	        let Some(delta) = &self.delta else {
198	            return Ok(());
199	        };
200	
201	        if delta.schema != SCHEMA_VERSION {
202	            return Err(Error::Manifest(format!(
203	                "unsupported delta schema {}, this build implements {SCHEMA_VERSION}",
204	                delta.schema
205	            )));
206	        }
207	
208	        if delta.hash_algo != HASH_ALGO {
209	            return Err(Error::Manifest(format!(
210	                "manifest hashes are {:?} but this build computes {HASH_ALGO:?}",
211	                delta.hash_algo
212	            )));
213	        }
214	
215	        for (platform, entry) in &delta.platforms {
216	            if entry.target_version != self.version {
217	                return Err(Error::Manifest(format!(
218	                    "delta entry for {platform} targets {} but the release is {}",
219	                    entry.target_version, self.version
220	                )));
221	            }
222	
223	            // A platform with patches but no full-download target would leave a
224	            // client with nothing to fall back to.
225	            let Some(tauri) = self.platforms.get(platform) else {
226	                return Err(Error::Manifest(format!(
227	                    "delta entry for {platform} has no matching full-download target"
228	                )));
229	            };
230	
231	            if tauri.signature != entry.signature {
232	                return Err(Error::Manifest(format!(
233	                    "signature mismatch for {platform}: the delta and full-download \
234	                     layers describe the same installer and must carry the same signature"
235	                )));
236	            }
237	
238	            // Fail on a malformed digest here rather than after a patch has been
239	            // downloaded and applied.
240	            FileHash::from_hex(&entry.target_installer_blake3)?;
241	
242	            for (from, patch) in &entry.patches {
243	                FileHash::from_hex(&patch.patch_blake3)?;
244	                if from == &entry.target_version {
245	                    return Err(Error::Manifest(format!(
246	                        "delta entry for {platform} patches {from} to itself"
247	                    )));
248	                }
249	            }
250	        }
251	
252	        Ok(())
253	    }
254	
255	    /// Look up the patch that upgrades `from_version` to this release on
256	    /// `platform`, along with the platform's delta metadata.
257	    ///
258	    /// Returns `None` whenever the delta path is not available — no delta layer,
259	    /// no entry for the platform, or no patch from that version. Every `None` is
260	    /// ordinary and means "download the full artifact".
261	    pub fn patch_for(
262	        &self,
263	        platform: &str,
264	        from_version: &str,
265	    ) -> Option<(&DeltaPlatform, &Patch)> {
266	        let delta = self.delta.as_ref()?;
267	        let entry = delta.platforms.get(platform)?;
268	        let patch = entry.patches.get(from_version)?;
269	        Some((entry, patch))
270	    }
271	}
