  1	//! The client half of an update: decide, fetch, rebuild, verify.
  2	//!
  3	//! This is what the Tauri plugin calls. It is deliberately free of any Tauri
  4	//! dependency and of any particular HTTP stack — transport arrives through the
  5	//! [`Fetch`] trait — for two reasons. It keeps the flow testable on any machine
  6	//! without a running app or a network, and it keeps the part that decides
  7	//! *what to install* separate from the part that knows *how to install it*,
  8	//! which is the only genuinely per-platform piece.
  9	//!
 10	//! [`plan_update`] cannot fail. It returns an [`UpdateSource`], and the caller's
 11	//! job is to act on whichever variant it gets — never to handle an error. Every
 12	//! way the delta path can go wrong resolves to
 13	//! [`UpdateSource::Full`], which is exactly what the official updater would have
 14	//! done unaided.
 15	
 16	use std::path::{Path, PathBuf};
 17	
 18	use crate::manifest::Manifest;
 19	use crate::{try_reconstruct, Error, FileHash, Reconstruction, TargetSpec};
 20	
 21	/// Fetches a URL into a local file.
 22	///
 23	/// Implemented by the host — the plugin uses Tauri's HTTP stack, tests use a
 24	/// map of canned responses. Errors are reported as plain strings because the
 25	/// only thing this layer does with a transport failure is fall back.
 26	pub trait Fetch {
 27	    /// Download `url`, writing the body to `out`.
 28	    fn fetch(&self, url: &str, out: &Path) -> Result<(), String>;
 29	}
 30	
 31	/// How the update should be obtained.
 32	#[derive(Debug)]
 33	#[must_use = "the caller must act on the chosen source"]
 34	pub enum UpdateSource {
 35	    /// A verified artifact, already rebuilt from a patch and ready to install.
 36	    ///
 37	    /// It has passed the size and digest gates. The caller still performs the
 38	    /// signature check, which needs the configured public key.
 39	    Delta {
 40	        /// The rebuilt artifact.
 41	        artifact: PathBuf,
 42	        /// Signature to validate it against, from the manifest.
 43	        signature: String,
 44	        /// Bytes actually downloaded.
 45	        downloaded: u64,
 46	        /// Bytes a full download would have cost.
 47	        would_have_downloaded: u64,
 48	    },
 49	
 50	    /// Download the complete artifact, as normal.
 51	    Full {
 52	        /// Where to download it from.
 53	        url: String,
 54	        /// Signature to validate it against.
 55	        signature: String,
 56	        /// Why the delta path was not taken, when it was attempted at all.
 57	        ///
 58	        /// For logging only. Every reason leads to the same action.
 59	        reason: Option<Error>,
 60	    },
 61	
 62	    /// The manifest publishes nothing for this platform.
 63	    Unavailable,
 64	}
 65	
 66	impl UpdateSource {
 67	    /// Fraction of a full download that was actually transferred, if a delta
 68	    /// was used.
 69	    pub fn downloaded_percent(&self) -> Option<f64> {
 70	        match self {
 71	            Self::Delta {
 72	                downloaded,
 73	                would_have_downloaded,
 74	                ..
 75	            } if *would_have_downloaded > 0 => {
 76	                Some(*downloaded as f64 / *would_have_downloaded as f64 * 100.0)
 77	            }
 78	            _ => None,
 79	        }
 80	    }
 81	}
 82	
 83	/// Decide how to obtain the release described by `manifest`, and if a patch can
 84	/// be used, fetch and apply it.
 85	///
 86	/// `base` is the installer the user already has, if it was cached after the last
 87	/// update. `None` is ordinary — the very first delta update has nothing to patch
 88	/// against, and so does anyone who installed from a download page.
 89	///
 90	/// Never fails.
 91	pub fn plan_update(
 92	    manifest: &Manifest,
 93	    platform: &str,
 94	    installed_version: &str,
 95	    base: Option<&Path>,
 96	    work_dir: &Path,
 97	    fetch: &dyn Fetch,
 98	) -> UpdateSource {
 99	    // No build for this platform at all — nothing to do, delta or otherwise.
100	    let Some(full) = manifest.platforms.get(platform) else {
101	        return UpdateSource::Unavailable;
102	    };
103	
104	    let fallback = |reason: Option<Error>| UpdateSource::Full {
105	        url: full.url.clone(),
106	        signature: full.signature.clone(),
107	        reason,
108	    };
109	
110	    // Each of these is an ordinary "no patch for you", not a failure: the
111	    // manifest may publish no delta layer, none for this platform, or none from
112	    // the version this user is on.
113	    let Some((entry, patch)) = manifest.patch_for(platform, installed_version) else {
114	        return fallback(None);
115	    };
116	
117	    let Some(base) = base else {
118	        return fallback(None);
119	    };
120	
121	    match attempt_delta(entry, patch, base, work_dir, fetch) {
122	        Ok(artifact) => UpdateSource::Delta {
123	            artifact,
124	            signature: entry.signature.clone(),
125	            downloaded: patch.patch_size,
126	            would_have_downloaded: entry.target_installer_size,
127	        },
128	        Err(reason) => fallback(Some(reason)),
129	    }
130	}
131	
132	fn attempt_delta(
133	    entry: &crate::manifest::DeltaPlatform,
134	    patch: &crate::manifest::Patch,
135	    base: &Path,
136	    work_dir: &Path,
137	    fetch: &dyn Fetch,
138	) -> Result<PathBuf, Error> {
139	    std::fs::create_dir_all(work_dir).map_err(|e| Error::io("create", work_dir, e))?;
140	
141	    let patch_path = work_dir.join("update.patch");
142	    fetch
143	        .fetch(&patch.patch_url, &patch_path)
144	        .map_err(|e| Error::Fetch(format!("downloading the patch: {e}")))?;
145	
146	    // Check the patch against the manifest before spending anything applying
147	    // it. A truncated or tampered download is caught here, cheaply.
148	    let expected = FileHash::from_hex(&patch.patch_blake3)?;
149	    let actual = FileHash::of_file(&patch_path)?;
150	    if actual != expected {
151	        return Err(Error::ChecksumMismatch {
152	            path: patch_path,
153	            expected: expected.to_hex(),
154	            actual: actual.to_hex(),
155	        });
156	    }
157	
158	    let target = TargetSpec::new(
159	        &patch.backend_id,
160	        entry.target_installer_size,
161	        &entry.target_installer_blake3,
162	    )?;
163	
164	    let artifact = work_dir.join("update.artifact");
165	    match try_reconstruct(base, &patch_path, &artifact, &target) {
166	        Reconstruction::Verified(path) => {
167	            // The patch has done its job; it can be large.
168	            let _ = std::fs::remove_file(&patch_path);
169	            Ok(path)
170	        }
171	        Reconstruction::FallBack(reason) => {
172	            let _ = std::fs::remove_file(&patch_path);
173	            Err(reason)
174	        }
175	    }
176	}
