  1	//! Binary delta updates for Tauri v2 — a wrapper around `tauri-plugin-updater`.
  2	//!
  3	//! This plugin does not install anything itself. It makes the *download* smaller
  4	//! by rebuilding the installer artifact from a patch, verifies it, and hands the
  5	//! result to the official updater's own install step.
  6	//!
  7	//! # Layering
  8	//!
  9	//! The interesting logic is in [`flow`], which has no Tauri dependency at all.
 10	//! Its two boundaries — the network and the installer — are traits, so the whole
 11	//! update path is testable without a running app. This module is the thin Tauri
 12	//! glue: an HTTP implementation of `Fetch`, an [`InstallHandoff`] over
 13	//! `tauri_plugin_updater::Update`, and the plugin registration.
 14	//!
 15	//! # Safety
 16	//!
 17	//! Tauri verifies signatures inside `Update::download()`, which the delta path
 18	//! bypasses by definition, and `Update::install()` verifies nothing. This
 19	//! plugin's own check is therefore the only one — see `docs/DECISIONS.md` #10 —
 20	//! and [`InstallHandoff::install`] takes a
 21	//! [`VerifiedArtifact`](tauri_updater_delta_core::VerifiedArtifact), which only
 22	//! successful verification can produce. An unverified install is not
 23	//! expressible.
 24	
 25	#![forbid(unsafe_code)]
 26	#![warn(missing_docs)]
 27	
 28	pub mod flow;
 29	mod http;
 30	mod tauri_glue;
 31	
 32	pub use flow::{run_update, Context, InstallHandoff, Outcome};
 33	pub use http::HttpFetch;
 34	pub use tauri_glue::{Builder, Config, TauriInstall};
 35	
 36	/// Convenience alias for results produced by this crate.
 37	pub type Result<T> = std::result::Result<T, Error>;
 38	
 39	/// Anything that can go wrong running an update.
 40	#[derive(Debug, thiserror::Error)]
 41	#[non_exhaustive]
 42	pub enum Error {
 43	    /// A download failed.
 44	    #[error("{0}")]
 45	    Fetch(String),
 46	
 47	    /// A filesystem operation failed.
 48	    #[error("{0}")]
 49	    Io(String),
 50	
 51	    /// The manifest was unusable.
 52	    #[error("{0}")]
 53	    Manifest(String),
 54	
 55	    /// Signature verification failed.
 56	    ///
 57	    /// Never recoverable by falling back: a manifest whose signature does not
 58	    /// check out cannot be trusted to describe a safe full download either.
 59	    #[error("{0}")]
 60	    Signature(String),
 61	
 62	    /// The installer rejected the artifact.
 63	    #[error("install failed: {0}")]
 64	    Install(String),
 65	}
  1	//! The update flow, from manifest URL to a verified artifact handed to an installer.
  2	//!
  3	//! Both boundaries are traits — [`Fetch`] for the network,
  4	//! [`InstallHandoff`] for the platform installer — so this whole path is
  5	//! exercised in tests with no server, no Tauri runtime and no filesystem
  6	//! installer. The Tauri-specific implementations are thin wrappers around them.
  7	//!
  8	//! # The safety invariant, end to end
  9	//!
 10	//! Two things cannot be expressed here, by construction rather than by care:
 11	//!
 12	//! - **An update that fails.** [`plan_update`] returns
 13	//!   `Delta | Full | Unavailable`, so a delta failure resolves to a full
 14	//!   download rather than an error.
 15	//! - **An unverified install.** [`InstallHandoff::install`] takes a
 16	//!   [`VerifiedArtifact`], which only `verify_artifact` can produce. Since
 17	//!   Tauri does not verify what it is handed (see `docs/DECISIONS.md` #10),
 18	//!   this is the sole gate — so it is the compiler's job, not a reviewer's.
 19	
 20	use std::path::Path;
 21	
 22	use tauri_updater_delta_core::client::{plan_update, Fetch, UpdateSource};
 23	use tauri_updater_delta_core::{verify_artifact, Manifest, VerifiedArtifact};
 24	
 25	use crate::{Error, Result};
 26	
 27	/// Hands a verified artifact to whatever actually installs it.
 28	///
 29	/// Takes a [`VerifiedArtifact`] rather than bytes: an unverified install is not
 30	/// something a caller can express.
 31	pub trait InstallHandoff {
 32	    /// Install the artifact. The signature has already been checked.
 33	    fn install(&self, artifact: &VerifiedArtifact) -> Result<()>;
 34	}
 35	
 36	/// What an update run did.
 37	#[derive(Debug, PartialEq, Eq)]
 38	pub enum Outcome {
 39	    /// Installed from a patch.
 40	    InstalledFromDelta {
 41	        /// Bytes downloaded.
 42	        downloaded: u64,
 43	        /// Bytes a full download would have cost.
 44	        saved_against: u64,
 45	    },
 46	    /// Installed after downloading the whole artifact.
 47	    InstalledFromFullDownload,
 48	    /// Nothing published for this platform.
 49	    Unavailable,
 50	}
 51	
 52	/// Everything the flow needs to know about the host.
 53	pub struct Context<'a> {
 54	    /// Tauri platform identifier, e.g. `"linux-x86_64"`.
 55	    pub platform: &'a str,
 56	    /// Version currently installed.
 57	    pub current_version: &'a str,
 58	    /// Base64 minisign public key, as in `tauri.conf.json`.
 59	    pub pubkey: &'a str,
 60	    /// Previously cached installer, if any.
 61	    pub base: Option<&'a Path>,
 62	    /// Scratch directory for the patch and the rebuilt artifact.
 63	    pub work_dir: &'a Path,
 64	}
 65	
 66	/// Fetch the manifest, take the cheapest safe path to the release, install it.
 67	///
 68	/// The delta path is attempted when it can be; anything wrong with it results
 69	/// in the full download the official updater would have performed anyway.
 70	pub fn run_update(
 71	    manifest_url: &str,
 72	    ctx: &Context<'_>,
 73	    fetch: &dyn Fetch,
 74	    handoff: &dyn InstallHandoff,
 75	) -> Result<Outcome> {
 76	    let manifest_path = ctx.work_dir.join("manifest.json");
 77	    std::fs::create_dir_all(ctx.work_dir)
 78	        .map_err(|e| Error::Io(format!("creating {}: {e}", ctx.work_dir.display())))?;
 79	
 80	    fetch
 81	        .fetch(manifest_url, &manifest_path)
 82	        .map_err(|e| Error::Fetch(format!("fetching the manifest: {e}")))?;
 83	
 84	    let text = std::fs::read_to_string(&manifest_path)
 85	        .map_err(|e| Error::Io(format!("reading the manifest: {e}")))?;
 86	    let manifest = Manifest::from_json(&text).map_err(|e| Error::Manifest(e.to_string()))?;
 87	
 88	    let source = plan_update(
 89	        &manifest,
 90	        ctx.platform,
 91	        ctx.current_version,
 92	        ctx.base,
 93	        ctx.work_dir,
 94	        fetch,
 95	    );
 96	
 97	    match source {
 98	        UpdateSource::Unavailable => Ok(Outcome::Unavailable),
 99	
100	        UpdateSource::Delta {
101	            artifact,
102	            signature,
103	            downloaded,
104	            would_have_downloaded,
105	        } => {
106	            let bytes = std::fs::read(&artifact)
107	                .map_err(|e| Error::Io(format!("reading the rebuilt artifact: {e}")))?;
108	
109	            // The reconstruction already matched the manifest's digest. This is
110	            // the separate question of whether the release process actually
111	            // published it — and nothing else will ask it.
112	            match verify_artifact(bytes, &signature, ctx.pubkey) {
113	                Ok(verified) => {
114	                    handoff.install(&verified)?;
115	                    let _ = std::fs::remove_file(&artifact);
116	                    Ok(Outcome::InstalledFromDelta {
117	                        downloaded,
118	                        saved_against: would_have_downloaded,
119	                    })
120	                }
121	                Err(_) => {
122	                    // A rebuilt artifact that matches the digest but not the
123	                    // signature means the manifest itself is not trustworthy.
124	                    // Falling back would download an artifact described by that
125	                    // same manifest, so there is nothing safe to fall back to.
126	                    let _ = std::fs::remove_file(&artifact);
127	                    Err(Error::Signature(
128	                        "the rebuilt artifact did not match the manifest's signature".to_owned(),
129	                    ))
130	                }
131	            }
132	        }
133	
134	        UpdateSource::Full { url, signature, .. } => {
135	            let full = ctx.work_dir.join("full.artifact");
136	            fetch
137	                .fetch(&url, &full)
138	                .map_err(|e| Error::Fetch(format!("downloading the full artifact: {e}")))?;
139	
140	            let bytes = std::fs::read(&full)
141	                .map_err(|e| Error::Io(format!("reading the downloaded artifact: {e}")))?;
142	            let verified = verify_artifact(bytes, &signature, ctx.pubkey)
143	                .map_err(|e| Error::Signature(e.to_string()))?;
144	
145	            handoff.install(&verified)?;
146	            let _ = std::fs::remove_file(&full);
147	            Ok(Outcome::InstalledFromFullDownload)
148	        }
149	    }
150	}
