  1	//! The network boundary: a blocking HTTP implementation of [`Fetch`].
  2	//!
  3	//! Blocking rather than async on purpose. The work either side of a download —
  4	//! hashing hundreds of megabytes, decompressing a patch — is CPU-bound and
  5	//! blocking anyway, so the whole flow belongs on a blocking task. Callers run it
  6	//! under `tauri::async_runtime::spawn_blocking`; using `reqwest::blocking`
  7	//! inside that is fine, and keeps [`Fetch`] a one-method trait that tests can
  8	//! implement with a `HashMap`.
  9	
 10	use std::io::Write;
 11	use std::path::Path;
 12	use std::time::Duration;
 13	
 14	use tauri_updater_delta_core::client::Fetch;
 15	
 16	/// Downloads over HTTPS, streaming to disk.
 17	pub struct HttpFetch {
 18	    client: reqwest::blocking::Client,
 19	}
 20	
 21	impl HttpFetch {
 22	    /// Build a fetcher with sensible timeouts.
 23	    pub fn new() -> std::result::Result<Self, String> {
 24	        let client = reqwest::blocking::Client::builder()
 25	            .user_agent(concat!(
 26	                "tauri-plugin-updater-delta/",
 27	                env!("CARGO_PKG_VERSION")
 28	            ))
 29	            .connect_timeout(Duration::from_secs(30))
 30	            // No overall timeout: a patch is small but an artifact may not be,
 31	            // and a slow connection is not a failure.
 32	            .build()
 33	            .map_err(|e| e.to_string())?;
 34	        Ok(Self { client })
 35	    }
 36	}
 37	
 38	impl Fetch for HttpFetch {
 39	    fn fetch(&self, url: &str, out: &Path) -> std::result::Result<(), String> {
 40	        let mut response = self
 41	            .client
 42	            .get(url)
 43	            .send()
 44	            .map_err(|e| format!("request failed: {e}"))?;
 45	
 46	        if !response.status().is_success() {
 47	            return Err(format!("server returned {}", response.status()));
 48	        }
 49	
 50	        let mut file = std::fs::File::create(out).map_err(|e| format!("creating {out:?}: {e}"))?;
 51	        // Streamed, so a large artifact is never fully resident here. It becomes
 52	        // resident only once, inside the verification token.
 53	        std::io::copy(&mut response, &mut file).map_err(|e| format!("writing {out:?}: {e}"))?;
 54	        file.flush().map_err(|e| format!("flushing {out:?}: {e}"))?;
 55	        Ok(())
 56	    }
 57	}
  1	//! The Tauri seam: registration, and the install handoff over `Update`.
  2	//!
  3	//! Everything Tauri-specific in this crate is here. The flow in [`crate::flow`]
  4	//! has no Tauri dependency, so this file is deliberately thin — if it grows,
  5	//! logic has probably leaked out of the layer that can be tested without an app.
  6	
  7	use tauri::plugin::{Builder as PluginBuilder, TauriPlugin};
  8	use tauri::{Manager, Runtime};
  9	use tauri_plugin_updater::Update;
 10	use tauri_updater_delta_core::VerifiedArtifact;
 11	
 12	use crate::flow::InstallHandoff;
 13	use crate::{Error, Result};
 14	
 15	/// Hands a verified artifact to the official updater's own install step.
 16	///
 17	/// This is the entire wrap-don't-replace design in one call: the bytes are
 18	/// bit-identical to what `Update::download` would have produced, so
 19	/// `Update::install` runs exactly as it always does — same installer logic, same
 20	/// platform handling, nothing forked.
 21	///
 22	/// It takes a [`VerifiedArtifact`] because `install` itself verifies nothing.
 23	/// See `docs/DECISIONS.md` #10.
 24	pub struct TauriInstall<'a> {
 25	    update: &'a Update,
 26	}
 27	
