 53	/// Builds the plugin.
 54	#[derive(Debug, Default)]
 55	pub struct Builder {
 56	    manifest_url: Option<String>,
 57	}
 58	
 59	impl Builder {
 60	    /// Start configuring the plugin.
 61	    pub fn new() -> Self {
 62	        Self::default()
 63	    }
 64	
 65	    /// Set the manifest URL. Required.
 66	    pub fn manifest_url(mut self, url: impl Into<String>) -> Self {
 67	        self.manifest_url = Some(url.into());
 68	        self
 69	    }
 70	
 71	    /// Build the plugin.
 72	    ///
 73	    /// # Errors
 74	    ///
 75	    /// If no manifest URL was set. Failing at registration is deliberate: a
 76	    /// plugin that silently does nothing because it was misconfigured is worse
 77	    /// than an app that refuses to start.
 78	    pub fn build<R: Runtime>(self) -> std::result::Result<TauriPlugin<R>, Error> {
 79	        let manifest_url = self.manifest_url.ok_or_else(|| {
 80	            Error::Manifest("a manifest URL is required: call Builder::manifest_url".to_owned())
 81	        })?;
 82	
 83	        Ok(PluginBuilder::new("updater-delta")
 84	            .setup(move |app, _api| {
 85	                app.manage(Config {
 86	                    manifest_url: manifest_url.clone(),
 87	                });
 88	                Ok(())
 89	            })
 90	            .build())
 91	    }
 92	}

  1	//! Deterministic AppImage-shaped fixtures, shared by every crate's tests.
  2	//!
  3	//! Real AppImages are an ELF runtime stub followed by a squashfs image, and that
  4	//! squashfs image is *compressed*. That detail is what makes these fixtures
  5	//! honest: the bulk of the file is high-entropy data that zstd cannot shrink on
  6	//! its own, so a small patch can only come from referencing the old artifact. A
  7	//! fixture made of compressible filler would flatter the engine and prove
  8	//! nothing.
  9	//!
 10	//! Generated rather than downloaded, so test suites run offline and produce
 11	//! identical numbers on every machine — which is what lets the patch bytes be
 12	//! pinned and cross-platform determinism be asserted rather than eyeballed.
 13	//!
 14	//! This crate is a test dependency and is never published.
 15	
 16	#![forbid(unsafe_code)]
 17	#![warn(missing_docs)]
 18	
 19	use std::path::{Path, PathBuf};
 20	
 21	/// ELF runtime stub — identical across releases.
 22	const STUB_LEN: usize = 128 * 1024;
 23	/// Payload preceding the app binary. Unchanged between the two versions.
 24	const ASSETS_HEAD_LEN: usize = 3 * 1024 * 1024;
 25	/// The app binary itself. Entirely rewritten by a release.
 26	const BINARY_LEN: usize = 256 * 1024;
 27	/// A newly added asset, inserted mid-file so everything after it shifts.
 28	const ADDED_LEN: usize = 128 * 1024;
 29	/// Payload following the app binary. Unchanged between the two versions.
 30	const ASSETS_TAIL_LEN: usize = 3 * 1024 * 1024;
 31	
 32	/// Version string of the installed artifact in [`appimage_pair`].
 33	pub const OLD_VERSION: &str = "1.0.0";
 34	/// Version string of the released artifact in [`appimage_pair`].
 35	pub const NEW_VERSION: &str = "1.0.1";
 36	
 37	/// Two versions of the same synthetic AppImage.
 38	pub struct Fixture {
 39	    /// The installed version — the base a patch is applied against.
 40	    pub old: PathBuf,
 41	    /// The released version — what the patch must reconstruct.
 42	    pub new: PathBuf,
 43	}
 44	
 45	/// Build a v1/v2 AppImage pair inside `dir`.
 46	///
 47	/// The difference between them models a routine release: the runtime stub and
 48	/// the bulk of the payload are byte-identical, the app binary is rewritten, and
 49	/// one new asset is inserted so that all following bytes shift position.
 50	///
 51	/// # Panics
 52	///
 53	/// If the two generated versions are identical. Every round-trip test reduces to
 54	/// "these two files can be reconciled", so a generator change that made them the
 55	/// same would leave the whole suite green while proving nothing.
 56	pub fn appimage_pair(dir: &Path) -> Fixture {
 57	    let stub = elf_stub();
 58	    let assets_head = pseudo_random(0xA55E_5EED, ASSETS_HEAD_LEN);
 59	    let assets_tail = pseudo_random(0x7A11_5EED, ASSETS_TAIL_LEN);
 60	    let binary_v1 = pseudo_random(0x0100_0000, BINARY_LEN);
 61	    let binary_v2 = pseudo_random(0x0101_0000, BINARY_LEN);
 62	    let added = pseudo_random(0x0ADD_ED00, ADDED_LEN);
 63	
 64	    let old = concat(&[&stub, &assets_head, &binary_v1, &assets_tail]);
 65	    let new = concat(&[&stub, &assets_head, &binary_v2, &added, &assets_tail]);
 66	
 67	    // Compared with `!=` rather than assert_ne! to avoid dumping 6 MiB of bytes
 68	    // into a panic message.
 69	    assert!(
 70	        old != new,
 71	        "fixture versions are identical — every round-trip test would be vacuous"
 72	    );
 73	
 74	    let old_path = dir.join(format!("app_{OLD_VERSION}.AppImage"));
 75	    let new_path = dir.join(format!("app_{NEW_VERSION}.AppImage"));
 76	    std::fs::write(&old_path, &old).expect("write old fixture");
 77	    std::fs::write(&new_path, &new).expect("write new fixture");
 78	
 79	    Fixture {
 80	        old: old_path,
 81	        new: new_path,
 82	    }
 83	}
 84	
 85	/// Write `contents` to `dir/name` and return the path.
 86	pub fn write(dir: &Path, name: &str, contents: &[u8]) -> PathBuf {
 87	    let path = dir.join(name);
 88	    std::fs::write(&path, contents).expect("write fixture");
 89	    path
 90	}
 91	
 92	/// Size of a file in bytes.
 93	pub fn size_of(path: &Path) -> u64 {
 94	    std::fs::metadata(path).expect("stat file").len()
 95	}
 96	
 97	/// An ELF header carrying the AppImage type-2 magic, then deterministic filler.
 98	fn elf_stub() -> Vec<u8> {
 99	    let mut stub = pseudo_random(0xE1F0_0000, STUB_LEN);
100	    stub[..8].copy_from_slice(&[0x7f, b'E', b'L', b'F', 2, 1, 1, 0]);
101	    // AppImage type 2 marks itself with "AI\x02" at offset 8.
102	    stub[8..11].copy_from_slice(&[b'A', b'I', 0x02]);
103	    stub
104	}
105	
106	fn concat(parts: &[&[u8]]) -> Vec<u8> {
107	    let mut out = Vec::with_capacity(parts.iter().map(|p| p.len()).sum());
108	    for part in parts {
109	        out.extend_from_slice(part);
110	    }
111	    out
112	}
113	
114	/// `len` bytes of high-entropy data, reproducible from `seed`.
115	///
116	/// xorshift64*: not a good random number generator, but deterministic across
117	/// platforms and compiler versions, which is what a fixture needs.
118	fn pseudo_random(seed: u64, len: usize) -> Vec<u8> {
119	    let mut state = seed | 1;
120	    let mut out = Vec::with_capacity(len);
121	    while out.len() < len {
122	        state ^= state >> 12;
123	        state ^= state << 25;
124	        state ^= state >> 27;
125	        let word = state.wrapping_mul(0x2545_F491_4F6C_DD1D);
126	        let take = (len - out.len()).min(8);
127	        out.extend_from_slice(&word.to_le_bytes()[..take]);
128	    }
129	    out
130	}
  1	//! The flagship test: prove a patch rebuilds an update artifact exactly.
  2	//!
  3	//! An AppImage is used because it is the first target platform and the simplest
  4	//! artifact — one self-contained file, no installer step, no code signature to
  5	//! preserve. Round-tripping one is pure file I/O, so this suite runs anywhere,
  6	//! including on the macOS machine this is being developed on.
  7	//!
  8	//! The happy path is only half the job. A delta engine that silently produces a
  9	//! *slightly wrong* artifact is far more dangerous than one that fails loudly,
 10	//! so most of what follows is failure cases: corrupt patches, truncated patches,
 11	//! and patches applied against the wrong base version. None of them may ever
 12	//! yield a file that passes verification.
 13	
 14	use tauri_updater_delta_fixtures as common;
 15	
 16	use std::path::Path;
 17	
 18	use tauri_updater_delta_core::backend::{backend_for, PatchBackend, ZstdBackend};
 19	use tauri_updater_delta_core::hash::{verify_file, FileHash};
 20	use tauri_updater_delta_core::Error;
 21	
 22	/// Diffing at level 19 is deliberately slow; tests that only care about
 23	/// correctness use a fast level instead.
 24	const FAST: i32 = 3;
 25	
 26	fn tempdir() -> tempfile::TempDir {
 27	    tempfile::tempdir().expect("create temp dir")
 28	}
 29	
 30	/// Assert that whatever `apply` did, the result is not a file that verifies as
 31	/// the real artifact. Either an error or a mismatch is acceptable; silence is
 32	/// not.
 33	fn assert_not_mistaken_for(result: tauri_updater_delta_core::Result<()>, out: &Path, real: &Path) {
 34	    if result.is_err() {
 35	        return;
 36	    }
 37	    let expected = FileHash::of_file(real).expect("hash real artifact");
 38	    assert!(
 39	        verify_file(out, &expected).is_err(),
 40	        "apply succeeded and the output verified as the real artifact, but the \
 41	         inputs were wrong — a bad patch must never be mistaken for a good one"
 42	    );
 43	}
