 45	#[test]
 46	fn rebuilds_the_new_appimage_exactly() {
 47	    let dir = tempdir();
 48	    let fixture = common::appimage_pair(dir.path());
 49	    let patch = dir.path().join("1.0.0-to-1.0.1.patch");
 50	    let rebuilt = dir.path().join("rebuilt.AppImage");
 51	
 52	    // Prove the two versions actually differ before proving they can be
 53	    // reconciled. Without this, the hash assertion below would pass trivially if
 54	    // the fixture generator ever stopped producing a real change — green,
 55	    // executed, and worthless.
 56	    let installed = FileHash::of_file(&fixture.old).expect("hash installed artifact");
 57	    let released = FileHash::of_file(&fixture.new).expect("hash released artifact");
 58	    assert_ne!(
 59	        installed, released,
 60	        "fixture versions are identical, so this test would prove nothing"
 61	    );
 62	
 63	    let backend = ZstdBackend::new();
 64	    backend
 65	        .diff(&fixture.old, &fixture.new, &patch)
 66	        .expect("diff should succeed");
 67	    backend
 68	        .apply(&fixture.old, &patch, &rebuilt)
 69	        .expect("apply should succeed");
 70	
 71	    // The assertion the whole project rests on.
 72	    verify_file(&rebuilt, &released).expect("rebuilt artifact must match the released one");
 73	
 74	    let full = common::size_of(&fixture.new);
 75	    let patch_size = common::size_of(&patch);
 76	
 77	    // A "patch" the size of the artifact is not a delta, and would make the
 78	    // reconstruction above true but pointless.
 79	    assert!(
 80	        patch_size < full / 2,
 81	        "patch ({patch_size} bytes) is not meaningfully smaller than the artifact ({full} bytes)"
 82	    );
 83	
 84	    println!(
 85	        "artifact {full} bytes ({:.2} MiB) | patch {patch_size} bytes ({:.2} MiB) | \
 86	         {:.2}% of a full download | {:.1}x smaller",
 87	        full as f64 / 1_048_576.0,
 88	        patch_size as f64 / 1_048_576.0,
 89	        patch_size as f64 / full as f64 * 100.0,
 90	        full as f64 / patch_size as f64,
 91	    );
 92	}
