286	/// Byte-for-byte digest of the patch produced from the fixture pair at the
287	/// default level. Pinned deliberately — see the test below.
288	const EXPECTED_PATCH_DIGEST: &str =
289	    "6892d72ab49da606bbeb98c04c8110aa145038492fbf849568590b99d8d5b546";
290	
291	/// Size of that same patch, asserted separately so a failure says *how* the
292	/// output moved rather than only that it did.
293	const EXPECTED_PATCH_SIZE: u64 = 393_782;
294	
295	#[test]
296	fn patch_bytes_are_identical_on_every_platform() {
297	    let dir = tempdir();
298	    let fixture = common::appimage_pair(dir.path());
299	    let patch = dir.path().join("delta.patch");
300	
301	    ZstdBackend::new()
302	        .diff(&fixture.old, &fixture.new, &patch)
303	        .expect("diff should succeed");
304	
305	    let size = common::size_of(&patch);
306	    let digest = FileHash::of_file(&patch).expect("hash patch");
307	    println!("patch {size} bytes | blake3 {digest}");
308	
309	    // This is the platform-agnostic claim, made testable.
310	    //
311	    // zstd-sys compiles a vendored C library, so the same inputs go through
312	    // Clang on Linux, Apple Clang on macOS and MSVC on Windows. Deterministic
313	    // output is expected — zstd is single-threaded here with every parameter
314	    // pinned — but "expected" is not "verified". Pinning the digest means each
315	    // platform's CI job independently reproduces the exact same bytes, and any
316	    // divergence turns that platform's job red on its own.
317	    //
318	    // The point is that the job's pass/fail *is* the evidence. Reading a size
319	    // out of three CI logs and comparing them by eye proves it once; this proves
320	    // it on every run, forever, and needs no access to the logs.
321	    //
322	    // Legitimate reasons for this to change: a zstd version bump, a fixture
323	    // change, or a change to the backend's compression parameters. All three are
324	    // deliberate and visible in the diff, so re-baseline both constants from the
325	    // printed line above and say why in the commit message. An *unexplained*
326	    // change, especially on one platform only, is a bug — do not re-baseline it.
327	    assert_eq!(
328	        size, EXPECTED_PATCH_SIZE,
329	        "patch size changed — see the comment above before re-baselining"
330	    );
331	    assert_eq!(
332	        digest.to_hex(),
333	        EXPECTED_PATCH_DIGEST,
334	        "patch bytes changed — see the comment above before re-baselining"
335	    );
336	}
  1	//! Gate: does the *actual* Tauri updater accept what `delta-release` signs?
  2	//!
  3	//! Everything in this project rests on one assumption — that the signature we
  4	//! write into a manifest is the signature Tauri's official updater will check
  5	//! and accept. If that is wrong, the delta path installs artifacts Tauri would
  6	//! have rejected, and every layer built on top has to be reworked. So it is
  7	//! settled here, before any client install flow exists.
  8	//!
  9	//! "`minisign-verify` accepts it" and "the Tauri updater accepts it" are
 10	//! different claims. This file tests the second one by reproducing
 11	//! `tauri-plugin-updater`'s verifier **verbatim** rather than writing an
 12	//! equivalent-looking check of our own.
 13	//!
 14	//! Reproduced from `tauri-plugin-updater` 2.10.1, `src/updater.rs:1453`:
 15	//!
 16	//! ```ignore
 17	//! fn verify_signature(data: &[u8], release_signature: &str, pub_key: &str) -> Result<bool> {
 18	//!     let pub_key_decoded = base64_to_string(pub_key)?;
 19	//!     let public_key = PublicKey::decode(&pub_key_decoded)?;
 20	//!     let signature_base64_decoded = base64_to_string(release_signature)?;
 21	//!     let signature = Signature::decode(&signature_base64_decoded)?;
 22	//!     public_key.verify(data, &signature, true)?;
 23	//!     Ok(true)
 24	//! }
 25	//!
 26	//! fn base64_to_string(base64_string: &str) -> Result<String> {
 27	//!     let decoded_string = &base64::engine::general_purpose::STANDARD.decode(base64_string)?;
