 59	/// Verbatim reproduction of `tauri-plugin-updater`'s `base64_to_string`.
 60	fn base64_to_string(base64_string: &str) -> std::result::Result<String, String> {
 61	    let decoded_string = base64::engine::general_purpose::STANDARD
 62	        .decode(base64_string)
 63	        .map_err(|e| e.to_string())?;
 64	    let result = std::str::from_utf8(&decoded_string)
 65	        .map_err(|e| e.to_string())?
