 70	/// Verbatim reproduction of `tauri-plugin-updater`'s `verify_signature`.
 71	///
 72	/// Deliberately not refactored, not tidied, and not made to return a nicer
 73	/// error type. Its value is in being the same code.
 74	fn tauri_verify_signature(
 75	    data: &[u8],
 76	    release_signature: &str,
 77	    pub_key: &str,
 78	) -> std::result::Result<bool, String> {
 79	    let pub_key_decoded = base64_to_string(pub_key)?;
 80	    let public_key = PublicKey::decode(&pub_key_decoded).map_err(|e| e.to_string())?;
 81	    let signature_base64_decoded = base64_to_string(release_signature)?;
 82	    let signature = Signature::decode(&signature_base64_decoded).map_err(|e| e.to_string())?;
 83	
 84	    public_key
 85	        .verify(data, &signature, true)
 86	        .map_err(|e| e.to_string())?;
 87	    Ok(true)
 88	}
