160	#[test]
161	fn the_signature_is_prehashed_and_that_is_the_path_tauri_takes() {
162	    // The specific question: Tauri passes `allow_legacy = true`, so a *legacy*
163	    // signature would also be accepted — meaning a passing verification alone
164	    // does not tell us which code path ran. `minisign` signs with
165	    // SIGALG_PREHASHED, and minisign-verify's `verify` branches on
166	    // `signature.is_prehashed` before `allow_legacy` is even consulted. Assert
167	    // the flag directly so we know the prehashed branch is the one being
168	    // exercised, rather than inferring it from a green test.
169	    let dir = tempfile::tempdir().expect("temp dir");
170	    let pair = keypair();
171	    let (manifest, installer) = publish(dir.path(), &pair);
172	    let bytes = std::fs::read(&installer).expect("read installer");
173	
174	    let raw = base64_to_string(&manifest.platforms[PLATFORM].signature).expect("base64 decode");
175	    let signature = Signature::decode(&raw).expect("decode signature");
176	
177	    // On the wire: minisign puts the algorithm in the first two bytes of the
178	    // signature line. "Ed" (0x45 0x64) is legacy, "ED" (0x45 0x44) is prehashed.
179	    let algorithm = raw
180	        .lines()
181	        .nth(1)
182	        .map(|line| {
183	            base64::engine::general_purpose::STANDARD
184	                .decode(line)
185	                .expect("signature line is base64")
186	        })
187	        .expect("signature has an algorithm line");
188	    assert_eq!(
189	        (algorithm[0], algorithm[1]),
190	        (0x45, 0x44),
191	        "delta-release must emit prehashed (ED) signatures, got {:?}",
192	        &algorithm[..2]
193	    );
194	
195	    // And through the public API, without relying on the wire format: verifying
196	    // with `allow_legacy = false` rejects any non-prehashed signature outright,
197	    // so success here can only mean the prehashed branch ran.
198	    let public_key =
199	        PublicKey::decode(&base64_to_string(&tauri_pubkey(&pair)).expect("decode key"))
200	            .expect("public key");
201	    public_key
202	        .verify(&bytes, &signature, false)
203	        .expect("signature must verify even with legacy signatures disallowed");
204	}
