 30	struct FakeServer(RefCell<HashMap<String, Vec<u8>>>);
 31	
 32	impl Fetch for FakeServer {
 33	    fn fetch(&self, url: &str, out: &Path) -> Result<(), String> {
 34	        let map = self.0.borrow();
 35	        let body = map.get(url).ok_or_else(|| format!("404 {url}"))?;
 36	        std::fs::write(out, body).map_err(|e| e.to_string())
 37	    }
 38	}
