 45	impl InstallHandoff for RecordingHandoff {
 46	    fn install(&self, artifact: &VerifiedArtifact) -> tauri_plugin_updater_delta::Result<()> {
 47	        self.installed
 48	            .borrow_mut()
 49	            .push(artifact.as_bytes().to_vec());
 50	        Ok(())
 51	    }
 52	}
