 70	/// Run the real release tooling and stand up a server holding what it produced.
 71	fn world(dir: &Path, pair: &KeyPair) -> World {
 72	    let fixture = tauri_updater_delta_fixtures::appimage_pair(dir);
 73	    let patch = dir.join("patch.zst");
 74	
 75	    let key = SigningKey::from_str(&pair.sk.to_box(None).expect("box key").into_string(), None)
 76	        .expect("load key");
 77	
 78	    let (manifest, _) = build_release(
 79	        &ReleaseRequest {
 80	            platform: PLATFORM,
 81	            version: "1.0.1",
 82	            from_version: "1.0.0",
 83	            previous_installer: &fixture.old,
 84	            new_installer: &fixture.new,
 85	            installer_url: INSTALLER_URL,
 86	            patch_url: PATCH_URL,
 87	            patch_out: &patch,
 88	            notes: None,
 89	            pub_date: None,
 90	        },
 91	        &key,
 92	        None,
 93	    )
 94	    .expect("release should build");
 95	
 96	    let files = HashMap::from([
 97	        (
 98	            MANIFEST_URL.to_owned(),
 99	            manifest.to_json().expect("serialise").into_bytes(),
100	        ),
101	        (
102	            PATCH_URL.to_owned(),
103	            std::fs::read(&patch).expect("read patch"),
104	        ),
105	        (
106	            INSTALLER_URL.to_owned(),
107	            std::fs::read(&fixture.new).expect("read installer"),
108	        ),
109	    ]);
110	
111	    World {
112	        server: FakeServer(RefCell::new(files)),
113	        pubkey: pubkey_b64(pair),
114	        base: fixture.old,
115	        released: fixture.new,
116	    }
117	}
