  1	//! The update flow over real HTTP, against artifacts the real release tool made.
  2	//!
  3	//! Every other suite drives the flow through a fake `Fetch`. That proves the
  4	//! logic and proves nothing about [`HttpFetch`] — the code that actually opens a
  5	//! socket, checks a status line and streams a body to disk. This closes that
  6	//! gap: a real server on a real port, real requests, real responses.
  7	//!
  8	//! Two boundaries remain fakes here, deliberately:
  9	//!
 10	//! - The **installer**, which is still a recording [`InstallHandoff`]. Replacing
 11	//!   it with `TauriInstall` needs a running app, which is the example-app work.
 12	//! - Nothing else. The manifest, the patch and the artifact are all produced by
 13	//!   `delta-release` and served over the wire.
 14	//!
 15	//! Assertions are strong-form throughout: not "no error was returned" but *what
 16	//! bytes reached the installer*, compared by BLAKE3 against the released
 17	//! artifact.
 18	
 19	mod support;
 20	
 21	use std::cell::RefCell;
 22	use std::path::Path;
 23	
 24	use base64::Engine as _;
 25	use minisign::KeyPair;
 26	use support::server::{read, Route, TestServer};
 27	use tauri_plugin_updater_delta::flow::{run_update, Context, InstallHandoff, Outcome};
 28	use tauri_plugin_updater_delta::{Error, HttpFetch};
 29	use tauri_updater_delta_core::{FileHash, VerifiedArtifact};
 30	use tauri_updater_delta_release::signing::SigningKey;
 31	use tauri_updater_delta_release::{build_release, ReleaseRequest};
 32	
 33	const PLATFORM: &str = "linux-x86_64";
 34	
 35	#[derive(Default)]
 36	struct RecordingHandoff {
 37	    installed: RefCell<Vec<Vec<u8>>>,
 38	}
 39	
 40	impl InstallHandoff for RecordingHandoff {
 41	    fn install(&self, artifact: &VerifiedArtifact) -> tauri_plugin_updater_delta::Result<()> {
 42	        self.installed
 43	            .borrow_mut()
 44	            .push(artifact.as_bytes().to_vec());
 45	        Ok(())
 46	    }
 47	}
 48	
 49	impl RecordingHandoff {
 50	    /// Strong form: exactly one install, and its bytes hash to `expected`.
 51	    fn assert_installed_exactly(&self, expected: &FileHash) {
 52	        let installed = self.installed.borrow();
 53	        assert_eq!(installed.len(), 1, "expected exactly one install");
 54	        assert_eq!(
 55	            FileHash::of_bytes(&installed[0]),
 56	            *expected,
 57	            "the installer received the wrong bytes"
 58	        );
 59	    }
 60	
 61	    fn assert_nothing_installed(&self) {
 62	        assert!(
 63	            self.installed.borrow().is_empty(),
 64	            "nothing should have reached the installer"
 65	        );
 66	    }
 67	}
