 69	fn keypair() -> KeyPair {
 70	    KeyPair::generate_encrypted_keypair(Some(String::new())).expect("generate keypair")
 71	}
 72	
 73	fn pubkey_b64(pair: &KeyPair) -> String {
 74	    base64::engine::general_purpose::STANDARD
 75	        .encode(pair.pk.to_box().expect("box pk").into_string())
 76	}
