 78	struct World {
 79	    server: TestServer,
 80	    pubkey: String,
 81	    base: std::path::PathBuf,
 82	    released_hash: FileHash,
 83	}
 84	
 85	/// Publish two versions with the real release tool and serve the result.
 86	fn world(dir: &Path, pair: &KeyPair) -> World {
 87	    let fixture = tauri_updater_delta_fixtures::appimage_pair(dir);
 88	
 89	    // The fixture already refuses to produce identical versions, so a vacuous
 90	    // pass is structurally impossible. Restate it here so this suite does not
 91	    // silently depend on a guarantee living in another crate.
 92	    let old_hash = FileHash::of_file(&fixture.old).expect("hash old");
 93	    let released_hash = FileHash::of_file(&fixture.new).expect("hash new");
 94	    assert_ne!(
 95	        old_hash, released_hash,
 96	        "fixture versions are identical, so every assertion below would be vacuous"
 97	    );
 98	
 99	    let server = TestServer::start();
100	    let patch = dir.join("patch.zst");
101	
102	    let key = SigningKey::from_str(&pair.sk.to_box(None).expect("box key").into_string(), None)
103	        .expect("load key");
104	
105	    let (manifest, _) = build_release(
106	        &ReleaseRequest {
107	            platform: PLATFORM,
108	            version: "1.0.1",
109	            from_version: "1.0.0",
110	            previous_installer: &fixture.old,
111	            new_installer: &fixture.new,
112	            installer_url: &server.url("/app_1.0.1.AppImage"),
113	            patch_url: &server.url("/patch.zst"),
114	            patch_out: &patch,
115	            notes: None,
116	            pub_date: None,
117	        },
118	        &key,
119	        None,
120	    )
121	    .expect("release should build");
122	
123	    server.serve(
124	        "/manifest.json",
125	        manifest.to_json().expect("serialise").into_bytes(),
126	    );
127	    server.serve("/patch.zst", read(&patch));
128	    server.serve("/app_1.0.1.AppImage", read(&fixture.new));
129	
130	    World {
131	        server,
132	        pubkey: pubkey_b64(pair),
133	        base: fixture.old,
134	        released_hash,
135	    }
136	}
