138	fn run(
139	    w: &World,
140	    handoff: &RecordingHandoff,
141	    work: &Path,
142	    base: Option<&Path>,
143	) -> tauri_plugin_updater_delta::Result<Outcome> {
144	    let fetch = HttpFetch::new().expect("build http client");
145	    run_update(
146	        &w.server.url("/manifest.json"),
147	        &Context {
148	            platform: PLATFORM,
149	            current_version: "1.0.0",
150	            pubkey: &w.pubkey,
151	            base,
152	            work_dir: work,
153	        },
154	        &fetch,
155	        handoff,
156	    )
157	}
