329	    let w = world(dir.path(), &pair);
330	    w.server.remove("/manifest.json");
331	    let handoff = RecordingHandoff::default();
332	
333	    let result = run(&w, &handoff, &dir.path().join("work"), Some(&w.base));
334	
335	    assert!(matches!(result, Err(Error::Fetch(_))));
336	    handoff.assert_nothing_installed();
337	}
  1	//! A real HTTP server for tests, built on `std::net` alone.
  2	//!
  3	//! Everything so far has driven the update flow through a fake [`Fetch`], which
  4	//! proves the logic but never once exercises the code that actually talks to a
  5	//! network. This serves the same artifacts over real TCP so [`HttpFetch`] —
  6	//! request, status handling, streaming to disk — is exercised too.
  7	//!
  8	//! No dependencies, and it binds port 0 so parallel tests cannot collide.
  9	//!
 10	//! [`Fetch`]: tauri_updater_delta_core::client::Fetch
 11	//! [`HttpFetch`]: tauri_plugin_updater_delta::HttpFetch
 12	
 13	use std::collections::HashMap;
 14	use std::io::{BufRead, BufReader, Read, Write};
 15	use std::net::{SocketAddr, TcpListener, TcpStream};
 16	use std::sync::atomic::{AtomicBool, Ordering};
 17	use std::sync::{Arc, Mutex};
 18	use std::thread;
 19	
 20	/// What the server should do with a request.
 21	#[derive(Clone)]
 22	pub enum Route {
 23	    /// Serve these bytes with 200.
 24	    Body(Vec<u8>),
 25	    /// Respond with this status and no useful body.
 26	    Status(u16),
 27	    /// Send headers, then fewer bytes than promised, then hang up.
 28	    ///
 29	    /// Models the interrupted download that a plain 404 does not.
 30	    Truncated(Vec<u8>),
 31	}
 32	
 33	type Routes = Arc<Mutex<HashMap<String, Route>>>;
 34	
 35	/// A test HTTP server on a background thread.
 36	pub struct TestServer {
 37	    addr: SocketAddr,
 38	    routes: Routes,
 39	    shutdown: Arc<AtomicBool>,
 40	}
 41	
 42	impl TestServer {
 43	    /// Start a server on an ephemeral port.
 44	    pub fn start() -> Self {
 45	        let listener = TcpListener::bind("127.0.0.1:0").expect("bind");
 46	        let addr = listener.local_addr().expect("local addr");
 47	        let routes: Routes = Arc::new(Mutex::new(HashMap::new()));
 48	        let shutdown = Arc::new(AtomicBool::new(false));
 49	
 50	        let thread_routes = Arc::clone(&routes);
 51	        let thread_shutdown = Arc::clone(&shutdown);
 52	        thread::spawn(move || {
 53	            for stream in listener.incoming() {
 54	                if thread_shutdown.load(Ordering::Relaxed) {
 55	                    break;
 56	                }
 57	                let Ok(stream) = stream else { continue };
 58	                let routes = Arc::clone(&thread_routes);
 59	                thread::spawn(move || {
 60	                    let _ = handle(stream, &routes);
 61	                });
 62	            }
 63	        });
 64	
 65	        Self {
 66	            addr,
 67	            routes,
 68	            shutdown,
 69	        }
 70	    }
 71	
 72	    /// Full URL for a path served by this instance.
 73	    pub fn url(&self, path: &str) -> String {
 74	        format!("http://{}{path}", self.addr)
 75	    }
 76	
 77	    /// Serve `bytes` at `path`.
 78	    pub fn serve(&self, path: &str, bytes: Vec<u8>) {
 79	        self.routes
 80	            .lock()
 81	            .expect("routes")
 82	            .insert(path.to_owned(), Route::Body(bytes));
 83	    }
 84	
 85	    /// Replace whatever is at `path`.
 86	    pub fn set(&self, path: &str, route: Route) {
 87	        self.routes
 88	            .lock()
 89	            .expect("routes")
 90	            .insert(path.to_owned(), route);
 91	    }
 92	
 93	    /// Stop serving `path` entirely — requests get 404.
 94	    pub fn remove(&self, path: &str) {
 95	        self.routes.lock().expect("routes").remove(path);
 96	    }
 97	}
 98	
 99	impl Drop for TestServer {
100	    fn drop(&mut self) {
101	        self.shutdown.store(true, Ordering::Relaxed);
102	        // Unblock the accept loop so the thread can notice and exit.
103	        let _ = std::net::TcpStream::connect(self.addr);
104	    }
105	}
106	
107	fn handle(mut stream: TcpStream, routes: &Routes) -> std::io::Result<()> {
108	    let mut reader = BufReader::new(stream.try_clone()?);
109	    let mut request_line = String::new();
110	    reader.read_line(&mut request_line)?;
111	
112	    // Drain headers so the client does not see a reset before we reply.
113	    loop {
114	        let mut line = String::new();
115	        if reader.read_line(&mut line)? == 0 || line == "\r\n" || line == "\n" {
116	            break;
117	        }
118	    }
119	
120	    let path = request_line.split_whitespace().nth(1).unwrap_or("/");
121	    let route = routes.lock().expect("routes").get(path).cloned();
122	
123	    match route {
124	        Some(Route::Body(body)) => {
125	            write!(
126	                stream,
127	                "HTTP/1.1 200 OK\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",
128	                body.len()
129	            )?;
130	            stream.write_all(&body)?;
131	        }
132	        Some(Route::Status(code)) => {
133	            write!(
134	                stream,
135	                "HTTP/1.1 {code} Error\r\nContent-Length: 0\r\nConnection: close\r\n\r\n"
136	            )?;
137	        }
138	        Some(Route::Truncated(body)) => {
139	            // Promise the full length, deliver half, then close.
140	            write!(
141	                stream,
142	                "HTTP/1.1 200 OK\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",
143	                body.len()
144	            )?;
145	            stream.write_all(&body[..body.len() / 2])?;
146	        }
147	        None => {
148	            write!(
149	                stream,
150	                "HTTP/1.1 404 Not Found\r\nContent-Length: 0\r\nConnection: close\r\n\r\n"
151	            )?;
152	        }
153	    }
154	
155	    stream.flush()?;
156	    Ok(())
157	}
158	
159	/// Read a whole file, for building routes from release output.
160	pub fn read(path: &std::path::Path) -> Vec<u8> {
161	    let mut bytes = Vec::new();
162	    std::fs::File::open(path)
163	        .expect("open")
164	        .read_to_end(&mut bytes)
165	        .expect("read");
166	    bytes
167	}

