  1	//! The full loop: release tooling produces a manifest, a client consumes it.
  2	//!
  3	//! Phase 1 proved a patch can rebuild an artifact. Phase 2 has to prove the two
  4	//! halves actually fit together — that what the release tool writes is exactly
  5	//! what a client needs, with nothing assumed and nothing passed out of band.
  6	//!
  7	//! So these tests never construct a manifest by hand. They run the real release
  8	//! path, serialise the result to JSON, throw the in-memory value away, and give
  9	//! the client nothing but that JSON and the files it names. Anything the tool
 10	//! forgets to record shows up here as a failure rather than as a surprise in
 11	//! Phase 3.
 12	//!
 13	//! The second half is the safety model: corrupt, truncated and wrong-base
 14	//! patches must each produce a fall back to the full download, never an install.
 15	
 16	use std::path::{Path, PathBuf};
 17	
 18	use base64::Engine as _;
 19	use minisign::KeyPair;
 20	use tauri_updater_delta_core::manifest::Manifest;
 21	use tauri_updater_delta_core::{try_reconstruct, FileHash, Reconstruction, TargetSpec};
 22	use tauri_updater_delta_release::signing::SigningKey;
 23	use tauri_updater_delta_release::{build_release, ReleaseRequest};
 24	
 25	const PLATFORM: &str = "linux-x86_64";
 26	
 27	/// A keypair that can be serialised and read back.
 28	///
 29	/// `generate_unencrypted_keypair()` leaves the secret key checksum zeroed and
 30	/// its output cannot be loaded again; an empty password writes the checksum and
 31	/// skips encryption, which is what an unencrypted key really looks like.
 32	fn keypair() -> KeyPair {
 33	    KeyPair::generate_encrypted_keypair(Some(String::new())).expect("generate keypair")
 34	}
 35	
 36	fn signing_key(pair: &KeyPair) -> SigningKey {
 37	    let text = pair.sk.to_box(None).expect("box key").into_string();
 38	    SigningKey::from_str(&text, None).expect("load key")
 39	}
 40	
 41	fn public_key_base64(pair: &KeyPair) -> String {
 42	    pair.pk
 43	        .to_box()
 44	        .expect("box public key")
 45	        .into_string()
 46	        .lines()
 47	        .nth(1)
 48	        .expect("public key line")
 49	        .to_owned()
 50	}
 51	
 52	/// What a release run leaves on disk, plus the JSON a client would fetch.
 53	struct Published {
 54	    manifest_json: String,
 55	    patch: PathBuf,
 56	    installed: PathBuf,
 57	    released: PathBuf,
 58	}
 59	
 60	/// Run the real release path over the shared AppImage fixtures.
 61	fn publish(dir: &Path, pair: &KeyPair) -> Published {
 62	    let fixture = tauri_updater_delta_fixtures::appimage_pair(dir);
 63	    let patch = dir.join("1.0.0-to-1.0.1.zst");
 64	
 65	    let request = ReleaseRequest {
 66	        platform: PLATFORM,
 67	        version: tauri_updater_delta_fixtures::NEW_VERSION,
 68	        from_version: tauri_updater_delta_fixtures::OLD_VERSION,
 69	        previous_installer: &fixture.old,
 70	        new_installer: &fixture.new,
 71	        installer_url: "https://releases.example.com/app_1.0.1.AppImage",
 72	        patch_url: "https://releases.example.com/1.0.0-to-1.0.1.zst",
 73	        patch_out: &patch,
 74	        notes: Some("Phase 2 end-to-end"),
 75	        pub_date: Some("2026-08-12T10:00:00Z"),
 76	    };
 77	
 78	    let (manifest, _) =
 79	        build_release(&request, &signing_key(pair), None).expect("release should build");
 80	
 81	    Published {
 82	        manifest_json: manifest.to_json().expect("serialise manifest"),
 83	        patch,
 84	        installed: fixture.old,
 85	        released: fixture.new,
 86	    }
 87	}
 88	
 89	/// Verify a signature the way Tauri's updater does.
 90	fn signature_is_valid(artifact: &Path, signature_b64: &str, pair: &KeyPair) -> bool {
 91	    let Ok(decoded) = base64::engine::general_purpose::STANDARD.decode(signature_b64) else {
 92	        return false;
 93	    };
 94	    let Ok(text) = String::from_utf8(decoded) else {
 95	        return false;
 96	    };
 97	    let Ok(signature) = minisign_verify::Signature::decode(&text) else {
 98	        return false;
 99	    };
100	    let Ok(public) = minisign_verify::PublicKey::from_base64(&public_key_base64(pair)) else {
101	        return false;
102	    };
103	    let Ok(bytes) = std::fs::read(artifact) else {
104	        return false;
105	    };
106	    public.verify(&bytes, &signature, true).is_ok()
107	}
108	
109	/// What a client concluded after trying the delta path.
110	#[derive(Debug, PartialEq, Eq)]
111	enum ClientOutcome {
112	    /// Rebuilt, hash-verified and signature-verified. Safe to install.
113	    Installed,
114	    /// Something was wrong. Download the full artifact instead.
115	    FullDownload,
116	}
117	
118	/// Simulate the client half of an update.
119	///
120	/// Deliberately given only the manifest JSON, the base artifact and a patch
121	/// file standing in for a download — the same inputs Phase 3's plugin will have.
122	fn run_client(
123	    manifest_json: &str,
124	    base: &Path,
125	    downloaded_patch: &Path,
126	    out: &Path,
127	    pair: &KeyPair,
128	) -> ClientOutcome {
129	    let Ok(manifest) = Manifest::from_json(manifest_json) else {
130	        return ClientOutcome::FullDownload;
131	    };
132	
133	    let Some((entry, patch)) =
134	        manifest.patch_for(PLATFORM, tauri_updater_delta_fixtures::OLD_VERSION)
135	    else {
136	        return ClientOutcome::FullDownload;
137	    };
138	
139	    // Check the patch against the manifest before spending anything applying it.
140	    match FileHash::of_file(downloaded_patch) {
141	        Ok(actual) if actual.to_hex() == patch.patch_blake3 => {}
142	        _ => return ClientOutcome::FullDownload,
143	    }
144	
145	    let Ok(target) = TargetSpec::new(
146	        &patch.backend_id,
147	        entry.target_installer_size,
148	        &entry.target_installer_blake3,
149	    ) else {
150	        return ClientOutcome::FullDownload;
151	    };
152	
153	    match try_reconstruct(base, downloaded_patch, out, &target) {
154	        Reconstruction::FallBack(_) => ClientOutcome::FullDownload,
155	        Reconstruction::Verified(path) => {
156	            // The hash proved reconstruction; the signature proves provenance.
157	            // Tauri's updater would do this check itself against the same field.
158	            if signature_is_valid(&path, &entry.signature, pair) {
159	                ClientOutcome::Installed
160	            } else {
161	                ClientOutcome::FullDownload
162	            }
163	        }
164	    }
165	}
166	
167	#[test]
168	fn a_client_updates_from_nothing_but_the_manifest() {
169	    let dir = tempfile::tempdir().expect("temp dir");
170	    let pair = keypair();
171	    let published = publish(dir.path(), &pair);
172	    let out = dir.path().join("rebuilt.AppImage");
173	
174	    let outcome = run_client(
175	        &published.manifest_json,
176	        &published.installed,
177	        &published.patch,
178	        &out,
179	        &pair,
180	    );
181	
182	    assert_eq!(
183	        outcome,
184	        ClientOutcome::Installed,
185	        "the manifest the tool wrote must be sufficient on its own"
186	    );
187	
188	    // And what it installed is the released artifact, byte for byte.
189	    let expected = FileHash::of_file(&published.released).expect("hash released artifact");
190	    let actual = FileHash::of_file(&out).expect("hash rebuilt artifact");
191	    assert_eq!(actual, expected, "the client installed the wrong bytes");
192	}
