280	fn a_manifest_signed_by_another_key_falls_back() {
281	    let dir = tempfile::tempdir().expect("temp dir");
282	    let published = publish(dir.path(), &keypair());
283	    let out = dir.path().join("rebuilt.AppImage");
284	
285	    // Reconstruction will succeed and the hash will match — only the signature
286	    // is wrong. This is the check that stops a correct-looking artifact from a
287	    // compromised or mistaken release process.
288	    let attacker = keypair();
289	    assert_eq!(
290	        run_client(
291	            &published.manifest_json,
292	            &published.installed,
293	            &published.patch,
294	            &out,
295	            &attacker
296	        ),
297	        ClientOutcome::FullDownload,
298	        "a valid reconstruction under the wrong key must not install"
299	    );
300	}
